#include <atomic>
#include <iostream>
#include <thread>
#include <vector>

std::atomic_int acnt;
int cnt;

void f()
{
    for (int n = 10000; n; --n)
    {
        ++acnt;
        ++cnt;
    }
}

int main()
{
    std::vector<std::thread> pool;
    for (int n = 0; n < 10; ++n)
        pool.emplace_back(f);

    for (auto& t : pool)
        t.join();

    std::cout << "The atomic counter is " << acnt << '\n'
              << "The non-atomic counter is " << cnt << '\n';
}

// Memory ordering options
enum memory_order {
    memory_order_relaxed,  // No ordering guarantees
    memory_order_consume,  // Dependency ordering (deprecated C++17)
    memory_order_acquire,  // No reads below can be reordered before this
    memory_order_release,  // No writes above can be reordered after this
    memory_order_acq_rel,  // Combined acquire and release
    memory_order_seq_cst   // Sequential consistency (default)
};
